using System.Collections;
using System.Threading.Tasks;
using Easy.DI;
using Easy.SceneFlow;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;

namespace Easy.Tests
{
    /// <summary>
    /// End-to-end Scene Flow composition against the sandbox scenes generated by
    /// the scaffold (Assets/Sandbox): startup, persistent contexts, switching,
    /// overlap rejection, rollback and forced reload.
    /// </summary>
    public sealed class SceneFlowCompositionTests
    {
        private const float TimeoutSeconds = 30f;
        private const string MainMenuKey = "main_menu";
        private const string SampleLevelKey = "sample_level";

        [UnityTest]
        public IEnumerator Startup_ComposesScenesAndSwitchesLevelsTransactionally()
        {
            SceneManager.LoadScene("Initialization", LoadSceneMode.Single);

            ILevelLoader loader = null;
            float timeoutAt = Time.realtimeSinceStartup + TimeoutSeconds;
            while (Time.realtimeSinceStartup < timeoutAt && (loader == null || !loader.IsInitialized))
            {
                SceneFlowContexts.TryResolveGlobal(out loader);
                yield return null;
            }

            Assert.IsNotNull(loader, "ILevelLoader was not published in GLOBAL.");
            Assert.IsTrue(loader.IsInitialized, "Scene flow did not finish startup.");
            Assert.AreEqual(MainMenuKey, loader.ActiveLevelKey);
            Assert.IsTrue(DIContext.TryResolve("SYSTEMS", out SceneRoleContext _));
            Assert.IsTrue(DIContext.TryResolve("UI", out SceneRoleContext _));
            Assert.IsTrue(DIContext.TryResolve("DEBUG", out SceneRoleContext _));
            Assert.IsTrue(DIContext.TryResolve("LEVEL", out LevelContext menu));
            Assert.AreEqual("MainMenu", menu.gameObject.scene.name);
            Assert.IsFalse(SceneManager.GetSceneByName("Initialization").isLoaded);
            Assert.IsFalse(SceneManager.GetSceneByName("Loading").isLoaded);

            Task<LevelLoadResult> toSample = loader.LoadLevelAsync(new LevelLoadRequest(SampleLevelKey));
            Task<LevelLoadResult> overlapping = loader.LoadLevelAsync(new LevelLoadRequest(MainMenuKey));
            Assert.IsTrue(overlapping.IsCompleted);
            Assert.AreEqual(LevelLoadStatus.Busy, overlapping.Result.Status);
            yield return Wait(toSample);
            Assert.AreEqual(LevelLoadStatus.Succeeded, toSample.Result.Status, toSample.Result.Message);
            Assert.AreEqual(SampleLevelKey, loader.ActiveLevelKey);
            Assert.IsFalse(SceneManager.GetSceneByName("MainMenu").isLoaded);
            Assert.AreEqual("SampleLevel", SceneManager.GetActiveScene().name);

            Task<LevelLoadResult> unknown = loader.LoadLevelAsync(new LevelLoadRequest("does_not_exist"));
            yield return Wait(unknown);
            Assert.AreEqual(LevelLoadStatus.UnknownLevel, unknown.Result.Status);

            Task<LevelLoadResult> missingEntry = loader.LoadLevelAsync(new LevelLoadRequest(MainMenuKey, "missing_entry"));
            yield return Wait(missingEntry);
            Assert.AreEqual(LevelLoadStatus.EntryPointMissing, missingEntry.Result.Status);
            Assert.AreEqual(SampleLevelKey, loader.ActiveLevelKey, "Failed transition keeps the previous level.");
            Assert.IsFalse(SceneManager.GetSceneByName("MainMenu").isLoaded, "Rejected candidate unloads.");
            Assert.IsTrue(DIContext.TryResolve("LEVEL", out LevelContext restored));
            Assert.AreEqual("SampleLevel", restored.gameObject.scene.name);

            Task<LevelLoadResult> reload = loader.LoadLevelAsync(new LevelLoadRequest(SampleLevelKey, forceReload: true));
            yield return Wait(reload);
            Assert.AreEqual(LevelLoadStatus.Succeeded, reload.Result.Status, reload.Result.Message);
        }

        [UnityTearDown]
        public IEnumerator TearDown()
        {
            Scene empty = SceneManager.CreateScene("SceneFlowTestEmpty");
            SceneManager.SetActiveScene(empty);
            for (int i = SceneManager.sceneCount - 1; i >= 0; i--)
            {
                Scene scene = SceneManager.GetSceneAt(i);
                if (scene != empty && scene.isLoaded)
                    yield return SceneManager.UnloadSceneAsync(scene);
            }

            SceneFlowInitializer initializer = Object.FindAnyObjectByType<SceneFlowInitializer>();
            if (initializer != null)
                Object.Destroy(initializer.gameObject);
            MainContext global = Object.FindAnyObjectByType<MainContext>();
            if (global != null)
                Object.Destroy(global.gameObject);
            yield return null;
        }

        private static IEnumerator Wait(Task task)
        {
            float timeoutAt = Time.realtimeSinceStartup + TimeoutSeconds;
            while (!task.IsCompleted && Time.realtimeSinceStartup < timeoutAt)
                yield return null;
            Assert.IsTrue(task.IsCompleted, "Level transition timed out.");
        }
    }
}
